     1→package lexer
     2→
     3→import (
     4→	"fmt"
     5→	"strings"
     6→	"unicode"
     7→)
     8→
     9→const (
    10→	maxInputSize      = 10_000_000
    11→	maxIdentifierLen  = 10_000
    12→	maxStringLen      = 1_000_000
    13→	maxNumberLen      = 100
    14→)
    15→
    16→// Lexer tokenizes V-compatible source code
    17→type Lexer struct {
    18→	input     string
    19→	pos       int
    20→	line      int
    21→	column    int
    22→	keywords  map[string]TokenType
    23→}
    24→
    25→// New creates a new lexer with input validation
    26→func New(input string) (*Lexer, error) {
    27→	// 보안: 입력 크기 제한
    28→	if len(input) > maxInputSize {
    29→		return nil, fmt.Errorf("input too large: %d bytes (max %d)", len(input), maxInputSize)
    30→	}
    31→
    32→	// 보안: NULL 바이트 확인 (단일 바이트로 검사)
    33→	for _, r := range input {
    34→		if r == 0 {
    35→			return nil, fmt.Errorf("input contains null bytes")
    36→		}
    37→	}
    38→
    39→	keywords := map[string]TokenType{
    40→		"fn":        TknFn,
    41→		"extern":    TknExtern,
    42→		"let":       TknLet,
    43→		"mut":       TknMut,
    44→		"const":     TknConst,
    45→		"if":        TknIf,
    46→		"else":      TknElse,
    47→		"for":       TknFor,
    48→		"in":        TknIn,
    49→		"match":     TknMatch,
    50→		"type":      TknType,
    51→		"struct":    TknStruct,
    52→		"interface": TknInterface,
    53→		"enum":      TknEnum,
    54→		"trait":     TknTrait,
    55→		"impl":      TknImpl,
    56→		"return":    TknReturn,
    57→		"module":    TknModule,
    58→		"import":    TknImport,
    59→		"true":      TknTrue,
    60→		"false":     TknFalse,
    61→		"none":      TknNone,
    62→	}
    63→
    64→	return &Lexer{
    65→		input:    input,
    66→		pos:      0,
    67→		line:     1,
    68→		column:   1,
    69→		keywords: keywords,
    70→	}, nil
    71→}
    72→
    73→// Tokenize returns all tokens from the input
    74→func (l *Lexer) Tokenize() ([]Token, error) {
    75→	var tokens []Token
    76→
    77→	for {
    78→		l.skipWhitespaceAndComments()
    79→
    80→		if l.isAtEnd() {
    81→			tokens = append(tokens, Token{
    82→				Type:   TknEof,
    83→				Text:   "",
    84→				Line:   l.line,
    85→				Column: l.column,
    86→			})
    87→			break
    88→		}
    89→
    90→		token, err := l.nextToken()
    91→		if err != nil {
    92→			return nil, err
    93→		}
    94→		tokens = append(tokens, token)
    95→	}
    96→
    97→	return tokens, nil
    98→}
    99→
   100→func (l *Lexer) nextToken() (Token, error) {
   101→	startLine := l.line
   102→	startColumn := l.column
   103→	startPos := l.pos
   104→
   105→	ch := l.current()
   106→	var token Token
   107→
   108→	switch ch {
   109→	case '(':
   110→		l.advance()
   111→		token = Token{TknLParen, "(", startLine, startColumn}
   112→	case ')':
   113→		l.advance()
   114→		token = Token{TknRParen, ")", startLine, startColumn}
   115→	case '{':
   116→		l.advance()
   117→		token = Token{TknLBrace, "{", startLine, startColumn}
   118→	case '}':
   119→		l.advance()
   120→		token = Token{TknRBrace, "}", startLine, startColumn}
   121→	case '[':
   122→		l.advance()
   123→		token = Token{TknLBracket, "[", startLine, startColumn}
   124→	case ']':
   125→		l.advance()
   126→		token = Token{TknRBracket, "]", startLine, startColumn}
   127→	case ',':
   128→		l.advance()
   129→		token = Token{TknComma, ",", startLine, startColumn}
   130→	case ';':
   131→		l.advance()
   132→		token = Token{TknSemicolon, ";", startLine, startColumn}
   133→	case '@':
   134→		l.advance()
   135→		token = Token{TknAt, "@", startLine, startColumn}
   136→	case '~':
   137→		l.advance()
   138→		token = Token{TknTilde, "~", startLine, startColumn}
   139→	case '+':
   140→		l.advance()
   141→		if l.current() == '=' {
   142→			l.advance()
   143→			token = Token{TknPlusAssign, "+=", startLine, startColumn}
   144→		} else {
   145→			token = Token{TknPlus, "+", startLine, startColumn}
   146→		}
   147→	case '-':
   148→		l.advance()
   149→		switch l.current() {
   150→		case '=':
   151→			l.advance()
   152→			token = Token{TknMinusAssign, "-=", startLine, startColumn}
   153→		case '>':
   154→			l.advance()
   155→			token = Token{TknArrow, "->", startLine, startColumn}
   156→		default:
   157→			token = Token{TknMinus, "-", startLine, startColumn}
   158→		}
   159→	case '*':
   160→		l.advance()
   161→		if l.current() == '=' {
   162→			l.advance()
   163→			token = Token{TknStarAssign, "*=", startLine, startColumn}
   164→		} else {
   165→			token = Token{TknStar, "*", startLine, startColumn}
   166→		}
   167→	case '/':
   168→		l.advance()
   169→		if l.current() == '=' {
   170→			l.advance()
   171→			token = Token{TknSlashAssign, "/=", startLine, startColumn}
   172→		} else {
   173→			token = Token{TknSlash, "/", startLine, startColumn}
   174→		}
   175→	case '%':
   176→		l.advance()
   177→		token = Token{TknPercent, "%", startLine, startColumn}
   178→	case '^':
   179→		l.advance()
   180→		token = Token{TknCaret, "^", startLine, startColumn}
   181→	case '&':
   182→		l.advance()
   183→		if l.current() == '&' {
   184→			l.advance()
   185→			token = Token{TknLogicalAnd, "&&", startLine, startColumn}
   186→		} else {
   187→			token = Token{TknAmpersand, "&", startLine, startColumn}
   188→		}
   189→	case '|':
   190→		l.advance()
   191→		if l.current() == '|' {
   192→			l.advance()
   193→			token = Token{TknLogicalOr, "||", startLine, startColumn}
   194→		} else {
   195→			token = Token{TknPipe, "|", startLine, startColumn}
   196→		}
   197→	case '!':
   198→		l.advance()
   199→		if l.current() == '=' {
   200→			l.advance()
   201→			token = Token{TknNe, "!=", startLine, startColumn}
   202→		} else {
   203→			token = Token{TknNot, "!", startLine, startColumn}
   204→		}
   205→	case '?':
   206→		l.advance()
   207→		token = Token{TknQuestion, "?", startLine, startColumn}
   208→	case '=':
   209→		l.advance()
   210→		switch l.current() {
   211→		case '=':
   212→			l.advance()
   213→			token = Token{TknEq, "==", startLine, startColumn}
   214→		case '>':
   215→			l.advance()
   216→			token = Token{TknFatArrow, "=>", startLine, startColumn}
   217→		default:
   218→			token = Token{TknAssign, "=", startLine, startColumn}
   219→		}
   220→	case '<':
   221→		l.advance()
   222→		switch l.current() {
   223→		case '=':
   224→			l.advance()
   225→			token = Token{TknLe, "<=", startLine, startColumn}
   226→		case '<':
   227→			l.advance()
   228→			token = Token{TknLeftShift, "<<", startLine, startColumn}
   229→		default:
   230→			token = Token{TknLt, "<", startLine, startColumn}
   231→		}
   232→	case '>':
   233→		l.advance()
   234→		switch l.current() {
   235→		case '=':
   236→			l.advance()
   237→			token = Token{TknGe, ">=", startLine, startColumn}
   238→		case '>':
   239→			l.advance()
   240→			token = Token{TknRightShift, ">>", startLine, startColumn}
   241→		default:
   242→			token = Token{TknGt, ">", startLine, startColumn}
   243→		}
   244→	case ':':
   245→		l.advance()
   246→		switch l.current() {
   247→		case ':':
   248→			l.advance()
   249→			token = Token{TknDoubleColon, "::", startLine, startColumn}
   250→		case '=':
   251→			l.advance()
   252→			token = Token{TknColonAssign, ":=", startLine, startColumn}
   253→		default:
   254→			token = Token{TknColon, ":", startLine, startColumn}
   255→		}
   256→	case '.':
   257→		l.advance()
   258→		switch l.current() {
   259→		case '.':
   260→			l.advance()
   261→			if l.current() == '=' {
   262→				l.advance()
   263→				token = Token{TknDotDotEq, "..=", startLine, startColumn}
   264→			} else {
   265→				token = Token{TknDoubleDot, "..", startLine, startColumn}
   266→			}
   267→		default:
   268→			token = Token{TknDot, ".", startLine, startColumn}
   269→		}
   270→	case '"':
   271→		l.advance()
   272→		text, err := l.readString(byte('"'))
   273→		if err != nil {
   274→			return Token{}, err
   275→		}
   276→		token = Token{TknString, text, startLine, startColumn}
   277→	case '\'':
   278→		l.advance()
   279→		text, err := l.readString(byte('\''))
   280→		if err != nil {
   281→			return Token{}, err
   282→		}
   283→		token = Token{TknString, text, startLine, startColumn}
   284→	case '`':
   285→		l.advance()
   286→		text, err := l.readRawString()
   287→		if err != nil {
   288→			return Token{}, err
   289→		}
   290→		token = Token{TknRawString, text, startLine, startColumn}
   291→	default:
   292→		if unicode.IsDigit(rune(ch)) {
   293→			return l.readNumber(startLine, startColumn)
   294→		} else if unicode.IsLetter(rune(ch)) || ch == '_' {
   295→			return l.readIdentifier(startLine, startColumn)
   296→		} else {
   297→			return Token{}, fmt.Errorf("unexpected character at %d:%d: '%c'", l.line, l.column, ch)
   298→		}
   299→	}
   300→
   301→	token.Line = startLine
   302→	token.Column = startColumn
   303→	if token.Text == "" {
   304→		token.Text = string(l.input[startPos:l.pos])
   305→	}
   306→
   307→	return token, nil
   308→}
   309→
   310→func (l *Lexer) readIdentifier(line, column int) (Token, error) {
   311→	start := l.pos
   312→
   313→	for !l.isAtEnd() && (unicode.IsLetter(rune(l.current())) || unicode.IsDigit(rune(l.current())) || l.current() == '_') {
   314→		l.advance()
   315→	}
   316→
   317→	ident := l.input[start:l.pos]
   318→
   319→	// Check if it's a keyword
   320→	if tknType, ok := l.keywords[ident]; ok {
   321→		return Token{tknType, ident, line, column}, nil
   322→	}
   323→
   324→	return Token{TknIdentifier, ident, line, column}, nil
   325→}
   326→
   327→func (l *Lexer) readNumber(line, column int) (Token, error) {
   328→	start := l.pos
   329→
   330→	// 정수 부분
   331→	for !l.isAtEnd() && unicode.IsDigit(rune(l.current())) {
   332→		l.advance()
   333→	}
   334→
   335→	// 부동소수점 확인
   336→	if l.current() == '.' && l.isDigitAt(l.pos+1) {
   337→		l.advance() // skip '.'
   338→
   339→		for !l.isAtEnd() && unicode.IsDigit(rune(l.current())) {
   340→			l.advance()
   341→		}
   342→
   343→		return Token{TknFloat, l.input[start:l.pos], line, column}, nil
   344→	}
   345→
   346→	return Token{TknInteger, l.input[start:l.pos], line, column}, nil
   347→}
   348→
   349→func (l *Lexer) readString(quote byte) (string, error) {
   350→	start := l.pos
   351→
   352→	for !l.isAtEnd() && l.current() != quote {
   353→		if l.current() == '\\' {
   354→			l.advance()
   355→			if !l.isAtEnd() {
   356→				l.advance()
   357→			}
   358→		} else {
   359→			if l.current() == '\n' {
   360→				l.line++
   361→				l.column = 0
   362→			}
   363→			l.advance()
   364→		}
   365→	}
   366→
   367→	if l.isAtEnd() {
   368→		return "", fmt.Errorf("unterminated string at line %d", l.line)
   369→	}
   370→
   371→	content := l.input[start:l.pos]
   372→	l.advance() // skip closing quote
   373→
   374→	return l.unescapeString(content), nil
   375→}
   376→
   377→func (l *Lexer) readRawString() (string, error) {
   378→	start := l.pos
   379→
   380→	for !l.isAtEnd() && l.current() != '`' {
   381→		if l.current() == '\n' {
   382→			l.line++
   383→			l.column = 0
   384→		}
   385→		l.advance()
   386→	}
   387→
   388→	if l.isAtEnd() {
   389→		return "", fmt.Errorf("unterminated raw string at line %d", l.line)
   390→	}
   391→
   392→	content := l.input[start:l.pos]
   393→	l.advance() // skip closing backtick
   394→
   395→	return content, nil
   396→}
   397→
   398→func (l *Lexer) unescapeString(s string) string {
   399→	var result strings.Builder
   400→	i := 0
   401→	for i < len(s) {
   402→		if s[i] == '\\' && i+1 < len(s) {
   403→			switch s[i+1] {
   404→			case 'n':
   405→				result.WriteByte('\n')
   406→				i += 2
   407→			case 't':
   408→				result.WriteByte('\t')
   409→				i += 2
   410→			case 'r':
   411→				result.WriteByte('\r')
   412→				i += 2
   413→			case '\\':
   414→				result.WriteByte('\\')
   415→				i += 2
   416→			case '"':
   417→				result.WriteByte('"')
   418→				i += 2
   419→			case '\'':
   420→				result.WriteByte('\'')
   421→				i += 2
   422→			default:
   423→				result.WriteByte(s[i+1])
   424→				i += 2
   425→			}
   426→		} else {
   427→			result.WriteByte(s[i])
   428→			i++
   429→		}
   430→	}
   431→	return result.String()
   432→}
   433→
   434→func (l *Lexer) skipWhitespaceAndComments() {
   435→	for !l.isAtEnd() {
   436→		switch l.current() {
   437→		case ' ', '\t', '\r':
   438→			l.advance()
   439→		case '\n':
   440→			l.line++
   441→			l.column = 0
   442→			l.advance()
   443→		case '/' :
   444→			if l.peekNext() == '/' {
   445→				// 한 줄 주석
   446→				for !l.isAtEnd() && l.current() != '\n' {
   447→					l.advance()
   448→				}
   449→			} else if l.peekNext() == '*' {
   450→				// 블록 주석
   451→				l.advance()
   452→				l.advance()
   453→				for !l.isAtEnd() {
   454→					if l.current() == '*' && l.peekNext() == '/' {
   455→						l.advance()
   456→						l.advance()
   457→						break
   458→					}
   459→					if l.current() == '\n' {
   460→						l.line++
   461→						l.column = 0
   462→					}
   463→					l.advance()
   464→				}
   465→			} else {
   466→				return
   467→			}
   468→		default:
   469→			return
   470→		}
   471→	}
   472→}
   473→
   474→func (l *Lexer) current() byte {
   475→	if l.isAtEnd() {
   476→		return 0
   477→	}
   478→	return l.input[l.pos]
   479→}
   480→
   481→func (l *Lexer) peekNext() byte {
   482→	if l.pos+1 >= len(l.input) {
   483→		return 0
   484→	}
   485→	return l.input[l.pos+1]
   486→}
   487→
   488→func (l *Lexer) isDigitAt(pos int) bool {
   489→	if pos >= len(l.input) {
   490→		return false
   491→	}
   492→	return unicode.IsDigit(rune(l.input[pos]))
   493→}
   494→
   495→func (l *Lexer) advance() {
   496→	if !l.isAtEnd() {
   497→		l.pos++
   498→		l.column++
   499→	}
   500→}
   501→
   502→func (l *Lexer) isAtEnd() bool {
   503→	return l.pos >= len(l.input)
   504→}
   505→

