     1→// Package parser implements V-compatible syntax parsing
     2→package parser
     3→
     4→import (
     5→	"fmt"
     6→	"strconv"
     7→
     8→	"fv2-lang/internal/ast"
     9→	"fv2-lang/internal/lexer"
    10→)
    11→
    12→// Parser converts tokens to AST
    13→type Parser struct {
    14→	tokens   []lexer.Token
    15→	pos      int
    16→	errors   []string
    17→}
    18→
    19→// New creates a new parser
    20→func New(tokens []lexer.Token) *Parser {
    21→	return &Parser{
    22→		tokens: tokens,
    23→		pos:    0,
    24→		errors: []string{},
    25→	}
    26→}
    27→
    28→// Parse parses tokens into an AST (with error recovery)
    29→func (p *Parser) Parse() (*ast.Program, error) {
    30→	var definitions []ast.Definition
    31→	var mainBody []ast.Statement
    32→
    33→	for !p.isAtEnd() {
    34→		if p.match(lexer.TknEof) {
    35→			break
    36→		}
    37→
    38→		// Handle import statements
    39→		if p.check(lexer.TknImport) {
    40→			def, err := p.parseImportStatement()
    41→			if err != nil {
    42→				p.errors = append(p.errors, err.Error())
    43→				p.synchronize()
    44→				continue
    45→			}
    46→			if def != nil {
    47→				definitions = append(definitions, def)
    48→			}
    49→		} else if p.check(lexer.TknExtern) {
    50→			// Handle extern function declaration
    51→			def, err := p.parseExternDef()
    52→			if err != nil {
    53→				p.errors = append(p.errors, err.Error())
    54→				p.synchronize()
    55→				continue
    56→			}
    57→			if def != nil {
    58→				definitions = append(definitions, def)
    59→			}
    60→		} else if p.check(lexer.TknFn) {
    61→			// Handle regular function definition
    62→			def, err := p.parseFunctionDef()
    63→			if err != nil {
    64→				p.errors = append(p.errors, err.Error())
    65→				p.synchronize() // Error recovery: skip to next definition
    66→				continue
    67→			}
    68→			if def != nil {
    69→				definitions = append(definitions, def)
    70→			}
    71→		} else if p.check(lexer.TknType) {
    72→			def, err := p.parseTypeDef()
    73→			if err != nil {
    74→				p.errors = append(p.errors, err.Error())
    75→				p.synchronize() // Error recovery
    76→				continue
    77→			}
    78→			if def != nil {
    79→				definitions = append(definitions, def)
    80→			}
    81→		} else if p.check(lexer.TknStruct) {
    82→			def, err := p.parseStructDef()
    83→			if err != nil {
    84→				p.errors = append(p.errors, err.Error())
    85→				p.synchronize() // Error recovery
    86→				continue
    87→			}
    88→			if def != nil {
    89→				definitions = append(definitions, def)
    90→			}
    91→		} else {
    92→			stmt, err := p.parseStatement()
    93→			if err != nil {
    94→				p.errors = append(p.errors, err.Error())
    95→				p.synchronize() // Error recovery
    96→				continue
    97→			}
    98→			if stmt != nil {
    99→				mainBody = append(mainBody, stmt)
   100→			}
   101→		}
   102→	}
   103→
   104→	// Return program even if there are errors (for partial parsing)
   105→	if len(p.errors) > 0 {
   106→		return &ast.Program{
   107→			Definitions: definitions,
   108→			MainBody:    mainBody,
   109→		}, fmt.Errorf("parse errors: %v", p.errors)
   110→	}
   111→
   112→	return &ast.Program{
   113→		Definitions: definitions,
   114→		MainBody:    mainBody,
   115→	}, nil
   116→}
   117→
   118→// parseFunctionDef parses a function definition
   119→func (p *Parser) parseFunctionDef() (*ast.FunctionDef, error) {
   120→	if !p.match(lexer.TknFn) {
   121→		return nil, nil
   122→	}
   123→
   124→	name := p.current().Text
   125→	if !p.match(lexer.TknIdentifier) {
   126→		return nil, fmt.Errorf("expected function name at %d:%d", p.current().Line, p.current().Column)
   127→	}
   128→
   129→	if !p.match(lexer.TknLParen) {
   130→		return nil, fmt.Errorf("expected '(' at %d:%d", p.current().Line, p.current().Column)
   131→	}
   132→
   133→	// Parse parameters
   134→	var params []ast.Parameter
   135→	if !p.check(lexer.TknRParen) {
   136→		for {
   137→			paramName := p.current().Text
   138→			if !p.match(lexer.TknIdentifier) {
   139→				return nil, fmt.Errorf("expected parameter name at %d:%d", p.current().Line, p.current().Column)
   140→			}
   141→
   142→			var paramType *ast.Type
   143→			if p.match(lexer.TknColon) {
   144→				// Type annotation
   145→				paramType = p.parseType()
   146→			}
   147→
   148→			params = append(params, ast.Parameter{
   149→				Name: paramName,
   150→				Type: paramType,
   151→			})
   152→
   153→			if !p.match(lexer.TknComma) {
   154→				break
   155→			}
   156→		}
   157→	}
   158→
   159→	if !p.match(lexer.TknRParen) {
   160→		return nil, fmt.Errorf("expected ')' at %d:%d", p.current().Line, p.current().Column)
   161→	}
   162→
   163→	// Parse return type (V syntax: type directly after params, no ->)
   164→	var returnType *ast.Type
   165→	if !p.check(lexer.TknLBrace) && !p.isAtEnd() {
   166→		// Look ahead to see if next is a type (identifier or keyword type)
   167→		if p.check(lexer.TknIdentifier) || p.isPrimitiveType() {
   168→			returnType = p.parseType()
   169→		}
   170→	}
   171→
   172→	// Parse body
   173→	if !p.match(lexer.TknLBrace) {
   174→		return nil, fmt.Errorf("expected '{' at %d:%d", p.current().Line, p.current().Column)
   175→	}
   176→
   177→	var body []ast.Statement
   178→	for !p.check(lexer.TknRBrace) && !p.isAtEnd() {
   179→		stmt, err := p.parseStatement()
   180→		if err != nil {
   181→			return nil, err
   182→		}
   183→		if stmt != nil {
   184→			body = append(body, stmt)
   185→		}
   186→	}
   187→
   188→	if !p.match(lexer.TknRBrace) {
   189→		return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   190→	}
   191→
   192→	return &ast.FunctionDef{
   193→		Name:       name,
   194→		Parameters: params,
   195→		ReturnType: returnType,
   196→		Body:       body,
   197→	}, nil
   198→}
   199→
   200→// parseTypeDef parses a type definition
   201→// V syntax: type UserId = i64
   202→func (p *Parser) parseTypeDef() (*ast.TypeDef, error) {
   203→	if !p.match(lexer.TknType) {
   204→		return nil, nil
   205→	}
   206→
   207→	name := p.current().Text
   208→	if !p.match(lexer.TknIdentifier) {
   209→		return nil, fmt.Errorf("expected type name at %d:%d", p.current().Line, p.current().Column)
   210→	}
   211→
   212→	if !p.match(lexer.TknAssign) {
   213→		return nil, fmt.Errorf("expected '=' at %d:%d", p.current().Line, p.current().Column)
   214→	}
   215→
   216→	// Parse the underlying type (simple type alias)
   217→	underlyingType := p.parseType()
   218→
   219→	return &ast.TypeDef{
   220→		Name: name,
   221→		Fields: []ast.Field{
   222→			{
   223→				Name: "value",
   224→				Type: underlyingType,
   225→			},
   226→		},
   227→	}, nil
   228→}
   229→
   230→// parseStructDef parses a struct definition
   231→// V syntax: struct Point { x i64, y i64 }
   232→// Field syntax: name type (no colon)
   233→func (p *Parser) parseStructDef() (*ast.StructDef, error) {
   234→	if !p.match(lexer.TknStruct) {
   235→		return nil, nil
   236→	}
   237→
   238→	name := p.current().Text
   239→	if !p.match(lexer.TknIdentifier) {
   240→		return nil, fmt.Errorf("expected struct name at %d:%d", p.current().Line, p.current().Column)
   241→	}
   242→
   243→	if !p.match(lexer.TknLBrace) {
   244→		return nil, fmt.Errorf("expected '{' at %d:%d", p.current().Line, p.current().Column)
   245→	}
   246→
   247→	var fields []ast.Field
   248→	for !p.check(lexer.TknRBrace) && !p.isAtEnd() {
   249→		isMutable := p.match(lexer.TknMut)
   250→
   251→		fieldName := p.current().Text
   252→		if !p.match(lexer.TknIdentifier) {
   253→			return nil, fmt.Errorf("expected field name at %d:%d", p.current().Line, p.current().Column)
   254→		}
   255→
   256→		// V syntax: field type (space-separated, no colon)
   257→		fieldType := p.parseType()
   258→
   259→		fields = append(fields, ast.Field{
   260→			Name:    fieldName,
   261→			Type:    fieldType,
   262→			Mutable: isMutable,
   263→		})
   264→
   265→		if !p.match(lexer.TknComma) {
   266→			break
   267→		}
   268→	}
   269→
   270→	if !p.match(lexer.TknRBrace) {
   271→		return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   272→	}
   273→
   274→	return &ast.StructDef{
   275→		Name:   name,
   276→		Fields: fields,
   277→	}, nil
   278→}
   279→
   280→// parseStatement parses a statement
   281→func (p *Parser) parseStatement() (ast.Statement, error) {
   282→	if p.match(lexer.TknLet) {
   283→		return p.parseLetStatement()
   284→	}
   285→	if p.match(lexer.TknConst) {
   286→		return p.parseConstStatement()
   287→	}
   288→	if p.match(lexer.TknIf) {
   289→		return p.parseIfStatement()
   290→	}
   291→	if p.match(lexer.TknFor) {
   292→		return p.parseForStatement()
   293→	}
   294→	if p.match(lexer.TknMatch) {
   295→		return p.parseMatchStatement()
   296→	}
   297→	if p.match(lexer.TknReturn) {
   298→		return p.parseReturnStatement()
   299→	}
   300→	if p.match(lexer.TknLBrace) {
   301→		return p.parseBlockStatement()
   302→	}
   303→
   304→	// Expression statement
   305→	expr, err := p.parseExpression()
   306→	if err != nil {
   307→		return nil, err
   308→	}
   309→
   310→	// Consume optional semicolon
   311→	p.match(lexer.TknSemicolon)
   312→
   313→	return &ast.ExpressionStatement{Expression: expr}, nil
   314→}
   315→
   316→// parseLetStatement parses a let binding
   317→func (p *Parser) parseLetStatement() (ast.Statement, error) {
   318→	isMutable := p.match(lexer.TknMut)
   319→
   320→	name := p.current().Text
   321→	if !p.match(lexer.TknIdentifier) {
   322→		return nil, fmt.Errorf("expected variable name at %d:%d", p.current().Line, p.current().Column)
   323→	}
   324→
   325→	var varType *ast.Type
   326→	if p.match(lexer.TknColon) {
   327→		varType = p.parseType()
   328→	}
   329→
   330→	var init ast.Expression
   331→	if p.match(lexer.TknAssign) || p.match(lexer.TknColonAssign) {
   332→		var err error
   333→		init, err = p.parseExpression()
   334→		if err != nil {
   335→			return nil, err
   336→		}
   337→	}
   338→
   339→	p.match(lexer.TknSemicolon)
   340→
   341→	return &ast.LetStatement{
   342→		Name:    name,
   343→		Type:    varType,
   344→		Init:    init,
   345→		Mutable: isMutable,
   346→	}, nil
   347→}
   348→
   349→// parseConstStatement parses a const binding
   350→func (p *Parser) parseConstStatement() (ast.Statement, error) {
   351→	name := p.current().Text
   352→	if !p.match(lexer.TknIdentifier) {
   353→		return nil, fmt.Errorf("expected constant name at %d:%d", p.current().Line, p.current().Column)
   354→	}
   355→
   356→	var varType *ast.Type
   357→	if p.match(lexer.TknColon) {
   358→		varType = p.parseType()
   359→	}
   360→
   361→	if !p.match(lexer.TknAssign) {
   362→		return nil, fmt.Errorf("expected '=' at %d:%d", p.current().Line, p.current().Column)
   363→	}
   364→
   365→	value, err := p.parseExpression()
   366→	if err != nil {
   367→		return nil, err
   368→	}
   369→
   370→	p.match(lexer.TknSemicolon)
   371→
   372→	return &ast.ConstStatement{
   373→		Name:  name,
   374→		Type:  varType,
   375→		Value: value,
   376→	}, nil
   377→}
   378→
   379→// parseIfStatement parses an if statement
   380→func (p *Parser) parseIfStatement() (ast.Statement, error) {
   381→	cond, err := p.parseExpression()
   382→	if err != nil {
   383→		return nil, err
   384→	}
   385→
   386→	if !p.match(lexer.TknLBrace) {
   387→		return nil, fmt.Errorf("expected '{' at %d:%d", p.current().Line, p.current().Column)
   388→	}
   389→
   390→	var thenBody []ast.Statement
   391→	for !p.check(lexer.TknRBrace) && !p.isAtEnd() {
   392→		stmt, err := p.parseStatement()
   393→		if err != nil {
   394→			return nil, err
   395→		}
   396→		if stmt != nil {
   397→			thenBody = append(thenBody, stmt)
   398→		}
   399→	}
   400→
   401→	if !p.match(lexer.TknRBrace) {
   402→		return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   403→	}
   404→
   405→	var elseBody []ast.Statement
   406→	if p.match(lexer.TknElse) {
   407→		if p.match(lexer.TknLBrace) {
   408→			for !p.check(lexer.TknRBrace) && !p.isAtEnd() {
   409→				stmt, err := p.parseStatement()
   410→				if err != nil {
   411→					return nil, err
   412→				}
   413→				if stmt != nil {
   414→					elseBody = append(elseBody, stmt)
   415→				}
   416→			}
   417→
   418→			if !p.match(lexer.TknRBrace) {
   419→				return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   420→			}
   421→		}
   422→	}
   423→
   424→	return &ast.IfStatement{
   425→		Condition: cond,
   426→		ThenBody:  thenBody,
   427→		ElseBody:  elseBody,
   428→	}, nil
   429→}
   430→
   431→// parseForStatement parses a for loop
   432→func (p *Parser) parseForStatement() (ast.Statement, error) {
   433→	varName := p.current().Text
   434→	if !p.match(lexer.TknIdentifier) {
   435→		return nil, fmt.Errorf("expected variable name at %d:%d", p.current().Line, p.current().Column)
   436→	}
   437→
   438→	if !p.match(lexer.TknIn) {
   439→		return nil, fmt.Errorf("expected 'in' at %d:%d", p.current().Line, p.current().Column)
   440→	}
   441→
   442→	iter, err := p.parseExpression()
   443→	if err != nil {
   444→		return nil, err
   445→	}
   446→
   447→	if !p.match(lexer.TknLBrace) {
   448→		return nil, fmt.Errorf("expected '{' at %d:%d", p.current().Line, p.current().Column)
   449→	}
   450→
   451→	var body []ast.Statement
   452→	for !p.check(lexer.TknRBrace) && !p.isAtEnd() {
   453→		stmt, err := p.parseStatement()
   454→		if err != nil {
   455→			return nil, err
   456→		}
   457→		if stmt != nil {
   458→			body = append(body, stmt)
   459→		}
   460→	}
   461→
   462→	if !p.match(lexer.TknRBrace) {
   463→		return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   464→	}
   465→
   466→	// Check if iter is a range (BinaryExpression with .. operator)
   467→	if binExpr, ok := iter.(*ast.BinaryExpression); ok && binExpr.Operator == ".." {
   468→		return &ast.ForRangeStatement{
   469→			Variable: varName,
   470→			Start:    binExpr.Left,
   471→			End:      binExpr.Right,
   472→			Body:     body,
   473→		}, nil
   474→	}
   475→
   476→	return &ast.ForStatement{
   477→		Variable: varName,
   478→		Iterator: iter,
   479→		Body:     body,
   480→	}, nil
   481→}
   482→
   483→// parseMatchStatement parses a match statement
   484→func (p *Parser) parseMatchStatement() (ast.Statement, error) {
   485→	expr, err := p.parseExpression()
   486→	if err != nil {
   487→		return nil, err
   488→	}
   489→
   490→	if !p.match(lexer.TknLBrace) {
   491→		return nil, fmt.Errorf("expected '{' at %d:%d", p.current().Line, p.current().Column)
   492→	}
   493→
   494→	var arms []ast.MatchArm
   495→	for !p.check(lexer.TknRBrace) && !p.isAtEnd() {
   496→		// Parse pattern
   497→		pattern, err := p.parsePattern()
   498→		if err != nil {
   499→			return nil, err
   500→		}
   501→
   502→		if !p.match(lexer.TknFatArrow) {
   503→			return nil, fmt.Errorf("expected '=>' at %d:%d", p.current().Line, p.current().Column)
   504→		}
   505→
   506→		// Parse body
   507→		var body []ast.Statement
   508→		if p.match(lexer.TknLBrace) {
   509→			for !p.check(lexer.TknRBrace) && !p.isAtEnd() {
   510→				stmt, err := p.parseStatement()
   511→				if err != nil {
   512→					return nil, err
   513→				}
   514→				if stmt != nil {
   515→					body = append(body, stmt)
   516→				}
   517→			}
   518→			if !p.match(lexer.TknRBrace) {
   519→				return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   520→			}
   521→		} else {
   522→			stmt, err := p.parseStatement()
   523→			if err != nil {
   524→				return nil, err
   525→			}
   526→			if stmt != nil {
   527→				body = append(body, stmt)
   528→			}
   529→		}
   530→
   531→		arms = append(arms, ast.MatchArm{
   532→			Pattern: pattern,
   533→			Body:    body,
   534→		})
   535→
   536→		if !p.match(lexer.TknComma) {
   537→			break
   538→		}
   539→	}
   540→
   541→	if !p.match(lexer.TknRBrace) {
   542→		return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   543→	}
   544→
   545→	return &ast.MatchStatement{
   546→		Expression: expr,
   547→		Arms:       arms,
   548→	}, nil
   549→}
   550→
   551→// parseReturnStatement parses a return statement
   552→func (p *Parser) parseReturnStatement() (ast.Statement, error) {
   553→	var value ast.Expression
   554→	if !p.check(lexer.TknSemicolon) && !p.check(lexer.TknRBrace) && !p.isAtEnd() {
   555→		var err error
   556→		value, err = p.parseExpression()
   557→		if err != nil {
   558→			return nil, err
   559→		}
   560→	}
   561→
   562→	p.match(lexer.TknSemicolon)
   563→
   564→	return &ast.ReturnStatement{Value: value}, nil
   565→}
   566→
   567→// parseBlockStatement parses a block statement
   568→func (p *Parser) parseBlockStatement() (ast.Statement, error) {
   569→	var statements []ast.Statement
   570→
   571→	for !p.check(lexer.TknRBrace) && !p.isAtEnd() {
   572→		stmt, err := p.parseStatement()
   573→		if err != nil {
   574→			return nil, err
   575→		}
   576→		if stmt != nil {
   577→			statements = append(statements, stmt)
   578→		}
   579→	}
   580→
   581→	if !p.match(lexer.TknRBrace) {
   582→		return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   583→	}
   584→
   585→	return &ast.BlockStatement{Statements: statements}, nil
   586→}
   587→
   588→// parseExpression parses an expression
   589→func (p *Parser) parseExpression() (ast.Expression, error) {
   590→	return p.parseBinaryExpression(0)
   591→}
   592→
   593→// parseBinaryExpression parses binary expressions with precedence
   594→func (p *Parser) parseBinaryExpression(minPrec int) (ast.Expression, error) {
   595→	left, err := p.parseUnary()
   596→	if err != nil {
   597→		return nil, err
   598→	}
   599→
   600→	for {
   601→		if p.isAtEnd() || !p.isOperator(p.current().Type) {
   602→			break
   603→		}
   604→
   605→		op := p.current()
   606→		prec := getPrecedence(op.Type)
   607→		if prec < minPrec {
   608→			break
   609→		}
   610→
   611→		p.advance()
   612→
   613→		right, err := p.parseBinaryExpression(prec + 1)
   614→		if err != nil {
   615→			return nil, err
   616→		}
   617→
   618→		left = &ast.BinaryExpression{
   619→			Left:     left,
   620→			Operator: op.Text,
   621→			Right:    right,
   622→		}
   623→	}
   624→
   625→	return left, nil
   626→}
   627→
   628→// parseUnary parses unary expressions
   629→func (p *Parser) parseUnary() (ast.Expression, error) {
   630→	if p.match(lexer.TknNot) {
   631→		operand, err := p.parseUnary()
   632→		if err != nil {
   633→			return nil, err
   634→		}
   635→		return &ast.UnaryExpression{
   636→			Operator: "!",
   637→			Operand:  operand,
   638→		}, nil
   639→	}
   640→
   641→	if p.match(lexer.TknMinus) {
   642→		operand, err := p.parseUnary()
   643→		if err != nil {
   644→			return nil, err
   645→		}
   646→		return &ast.UnaryExpression{
   647→			Operator: "-",
   648→			Operand:  operand,
   649→		}, nil
   650→	}
   651→
   652→	if p.match(lexer.TknAmpersand) {
   653→		operand, err := p.parseUnary()
   654→		if err != nil {
   655→			return nil, err
   656→		}
   657→		return &ast.UnaryExpression{
   658→			Operator: "&",
   659→			Operand:  operand,
   660→		}, nil
   661→	}
   662→
   663→	return p.parsePostfix()
   664→}
   665→
   666→// parsePostfix parses postfix expressions
   667→func (p *Parser) parsePostfix() (ast.Expression, error) {
   668→	expr, err := p.parsePrimary()
   669→	if err != nil {
   670→		return nil, err
   671→	}
   672→
   673→	for {
   674→		if p.match(lexer.TknLParen) {
   675→			// Function call
   676→			var args []ast.Expression
   677→			if !p.check(lexer.TknRParen) {
   678→				for {
   679→					arg, err := p.parseExpression()
   680→					if err != nil {
   681→						return nil, err
   682→					}
   683→					args = append(args, arg)
   684→
   685→					if !p.match(lexer.TknComma) {
   686→						break
   687→					}
   688→				}
   689→			}
   690→
   691→			if !p.match(lexer.TknRParen) {
   692→				return nil, fmt.Errorf("expected ')' at %d:%d", p.current().Line, p.current().Column)
   693→			}
   694→
   695→			expr = &ast.CallExpression{
   696→				Function:  expr,
   697→				Arguments: args,
   698→			}
   699→		} else if p.match(lexer.TknDot) {
   700→			// Field access or method call
   701→			fieldName := p.current().Text
   702→			if !p.match(lexer.TknIdentifier) {
   703→				return nil, fmt.Errorf("expected field name at %d:%d", p.current().Line, p.current().Column)
   704→			}
   705→
   706→			if p.match(lexer.TknLParen) {
   707→				// Method call
   708→				var args []ast.Expression
   709→				if !p.check(lexer.TknRParen) {
   710→					for {
   711→						arg, err := p.parseExpression()
   712→						if err != nil {
   713→							return nil, err
   714→						}
   715→						args = append(args, arg)
   716→
   717→						if !p.match(lexer.TknComma) {
   718→							break
   719→						}
   720→					}
   721→				}
   722→
   723→				if !p.match(lexer.TknRParen) {
   724→					return nil, fmt.Errorf("expected ')' at %d:%d", p.current().Line, p.current().Column)
   725→				}
   726→
   727→				expr = &ast.MethodCallExpression{
   728→					Object:    expr,
   729→					Method:    fieldName,
   730→					Arguments: args,
   731→				}
   732→			} else {
   733→				// Field access
   734→				expr = &ast.FieldExpression{
   735→					Object: expr,
   736→					Field:  fieldName,
   737→				}
   738→			}
   739→		} else if p.match(lexer.TknLBracket) {
   740→			// Index access
   741→			index, err := p.parseExpression()
   742→			if err != nil {
   743→				return nil, err
   744→			}
   745→
   746→			if !p.match(lexer.TknRBracket) {
   747→				return nil, fmt.Errorf("expected ']' at %d:%d", p.current().Line, p.current().Column)
   748→			}
   749→
   750→			expr = &ast.IndexExpression{
   751→				Object: expr,
   752→				Index:  index,
   753→			}
   754→		} else if p.match(lexer.TknQuestion) {
   755→			// Error propagation
   756→			expr = &ast.ErrorPropagation{Expression: expr}
   757→		} else {
   758→			break
   759→		}
   760→	}
   761→
   762→	return expr, nil
   763→}
   764→
   765→// parsePrimary parses primary expressions
   766→func (p *Parser) parsePrimary() (ast.Expression, error) {
   767→	// Literals
   768→	if p.match(lexer.TknInteger) {
   769→		val, err := strconv.ParseInt(p.previous().Text, 10, 64)
   770→		if err != nil {
   771→			return nil, fmt.Errorf("invalid integer: %s", p.previous().Text)
   772→		}
   773→		return &ast.IntegerLiteral{Value: val}, nil
   774→	}
   775→
   776→	if p.match(lexer.TknFloat) {
   777→		val, err := strconv.ParseFloat(p.previous().Text, 64)
   778→		if err != nil {
   779→			return nil, fmt.Errorf("invalid float: %s", p.previous().Text)
   780→		}
   781→		return &ast.FloatLiteral{Value: val}, nil
   782→	}
   783→
   784→	if p.match(lexer.TknString) {
   785→		return &ast.StringLiteral{Value: p.previous().Text}, nil
   786→	}
   787→
   788→	if p.match(lexer.TknTrue) {
   789→		return &ast.BoolLiteral{Value: true}, nil
   790→	}
   791→
   792→	if p.match(lexer.TknFalse) {
   793→		return &ast.BoolLiteral{Value: false}, nil
   794→	}
   795→
   796→	if p.match(lexer.TknNone) {
   797→		return &ast.NoneLiteral{}, nil
   798→	}
   799→
   800→	if p.match(lexer.TknIdentifier) {
   801→		return &ast.Identifier{Name: p.previous().Text}, nil
   802→	}
   803→
   804→	if p.match(lexer.TknLBracket) {
   805→		// Array literal
   806→		var elements []ast.Expression
   807→		if !p.check(lexer.TknRBracket) {
   808→			for {
   809→				elem, err := p.parseExpression()
   810→				if err != nil {
   811→					return nil, err
   812→				}
   813→				elements = append(elements, elem)
   814→
   815→				if !p.match(lexer.TknComma) {
   816→					break
   817→				}
   818→			}
   819→		}
   820→
   821→		if !p.match(lexer.TknRBracket) {
   822→			return nil, fmt.Errorf("expected ']' at %d:%d", p.current().Line, p.current().Column)
   823→		}
   824→
   825→		return &ast.ArrayExpression{Elements: elements}, nil
   826→	}
   827→
   828→	if p.match(lexer.TknIf) {
   829→		// Parse if expression
   830→		cond, err := p.parseExpression()
   831→		if err != nil {
   832→			return nil, err
   833→		}
   834→
   835→		if !p.match(lexer.TknLBrace) {
   836→			return nil, fmt.Errorf("expected '{' at %d:%d", p.current().Line, p.current().Column)
   837→		}
   838→
   839→		thenExpr, err := p.parseExpression()
   840→		if err != nil {
   841→			return nil, err
   842→		}
   843→
   844→		if !p.match(lexer.TknRBrace) {
   845→			return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   846→		}
   847→
   848→		var elseExpr ast.Expression
   849→		if p.match(lexer.TknElse) {
   850→			if p.match(lexer.TknLBrace) {
   851→				var err error
   852→				elseExpr, err = p.parseExpression()
   853→				if err != nil {
   854→					return nil, err
   855→				}
   856→
   857→				if !p.match(lexer.TknRBrace) {
   858→					return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   859→				}
   860→			}
   861→		}
   862→
   863→		return &ast.IfExpression{
   864→			Condition: cond,
   865→			ThenExpr:  thenExpr,
   866→			ElseExpr:  elseExpr,
   867→		}, nil
   868→	}
   869→
   870→	if p.match(lexer.TknLParen) {
   871→		expr, err := p.parseExpression()
   872→		if err != nil {
   873→			return nil, err
   874→		}
   875→
   876→		if !p.match(lexer.TknRParen) {
   877→			return nil, fmt.Errorf("expected ')' at %d:%d", p.current().Line, p.current().Column)
   878→		}
   879→
   880→		return expr, nil
   881→	}
   882→
   883→	return nil, fmt.Errorf("unexpected token: %v at %d:%d", p.current().Type, p.current().Line, p.current().Column)
   884→}
