   908→// parseType parses a type
   909→func (p *Parser) parseType() *ast.Type {
   910→	// Handle option types (?)
   911→	isOption := p.match(lexer.TknQuestion)
   912→
   913→	// Get base type
   914→	var typeName string
   915→	if p.match(lexer.TknIdentifier) {
   916→		typeName = p.previous().Text
   917→	} else {
   918→		typeName = "unknown"
   919→	}
   920→
   921→	// Handle array types (prefix [])
   922→	isArray := false
   923→	if p.check(lexer.TknLBracket) {
   924→		p.advance()
   925→		if p.match(lexer.TknRBracket) {
   926→			isArray = true
   927→		} else {
   928→			p.pos-- // backtrack
   929→		}
   930→	}
   931→
   932→	return &ast.Type{
   933→		Name:       typeName,
   934→		IsOption:   isOption,
   935→		IsArray:    isArray,
   936→		IsPrimitive: isPrimitiveType(typeName),
   937→	}
   938→}
