   940→// Helper methods
   941→
   942→func (p *Parser) current() lexer.Token {
   943→	if p.pos < len(p.tokens) {
   944→		return p.tokens[p.pos]
   945→	}
   946→	return lexer.Token{Type: lexer.TknEof}
   947→}
   948→
   949→func (p *Parser) previous() lexer.Token {
   950→	if p.pos > 0 {
   951→		return p.tokens[p.pos-1]
   952→	}
   953→	return lexer.Token{Type: lexer.TknEof}
   954→}
   955→
   956→func (p *Parser) advance() lexer.Token {
   957→	curr := p.current()
   958→	if !p.isAtEnd() {
   959→		p.pos++
   960→	}
   961→	return curr
   962→}
   963→
   964→func (p *Parser) match(types ...lexer.TokenType) bool {
   965→	for _, t := range types {
   966→		if p.check(t) {
   967→			p.advance()
   968→			return true
   969→		}
   970→	}
   971→	return false
   972→}
   973→
   974→func (p *Parser) check(t lexer.TokenType) bool {
   975→	if p.isAtEnd() {
   976→		return false
   977→	}
   978→	return p.current().Type == t
   979→}
   980→
   981→func (p *Parser) isAtEnd() bool {
   982→	return p.current().Type == lexer.TknEof
   983→}
