   985→func (p *Parser) isOperator(t lexer.TokenType) bool {
   986→	// Check if token is an operator
   987→	switch t {
   988→	case lexer.TknPlus, lexer.TknMinus, lexer.TknStar, lexer.TknSlash, lexer.TknPercent:
   989→		return true
   990→	case lexer.TknAmpersand, lexer.TknPipe, lexer.TknCaret, lexer.TknTilde:
   991→		return true
   992→	case lexer.TknLeftShift, lexer.TknRightShift:
   993→		return true
   994→	case lexer.TknEq, lexer.TknNe, lexer.TknLt, lexer.TknLe, lexer.TknGt, lexer.TknGe:
   995→		return true
   996→	case lexer.TknLogicalAnd, lexer.TknLogicalOr, lexer.TknNot:
   997→		return true
   998→	case lexer.TknDoubleDot:
   999→		return true
  1000→	default:
  1001→		return false
  1002→	}
  1003→}
  1004→
  1005→func getPrecedence(t lexer.TokenType) int {
  1006→	switch t {
  1007→	case lexer.TknLogicalOr:
  1008→		return 1
  1009→	case lexer.TknLogicalAnd:
  1010→		return 2
  1011→	case lexer.TknEq, lexer.TknNe, lexer.TknLt, lexer.TknLe, lexer.TknGt, lexer.TknGe:
  1012→		return 3
  1013→	case lexer.TknPlus, lexer.TknMinus:
  1014→		return 4
  1015→	case lexer.TknStar, lexer.TknSlash, lexer.TknPercent:
  1016→		return 5
  1017→	case lexer.TknCaret:
  1018→		return 6
  1019→	case lexer.TknDoubleDot:
  1020→		return 3 // Same as comparison for range expressions
  1021→	default:
  1022→		return 0
  1023→	}
  1024→}
