  1026→func (p *Parser) isPrimitiveType() bool {
  1027→	if p.current().Type == lexer.TknIdentifier {
  1028→		return isPrimitiveType(p.current().Text)
  1029→	}
  1030→	// Also check for V primitive keywords
  1031→	switch p.current().Type {
  1032→	case lexer.TknTrue, lexer.TknFalse:
  1033→		return true
  1034→	}
  1035→	return false
  1036→}
  1037→
  1038→func isPrimitiveType(name string) bool {
  1039→	switch name {
  1040→	case "i8", "i16", "i32", "i64", "u8", "u16", "u32", "u64", "f32", "f64", "bool", "string", "char", "int", "float":
  1041→		return true
  1042→	}
  1043→	return false
  1044→}
