  1074→// parseImportStatement parses an import statement
  1075→func (p *Parser) parseImportStatement() (*ast.ImportStatement, error) {
  1076→	if !p.match(lexer.TknImport) {
  1077→		return nil, nil
  1078→	}
  1079→
  1080→	if !p.match(lexer.TknString) {
  1081→		return nil, fmt.Errorf("expected string module name at %d:%d", p.current().Line, p.current().Column)
  1082→	}
  1083→
  1084→	module := p.previous().Text
  1085→	// Lexer already removes quotes, so use Text directly
  1086→	return &ast.ImportStatement{
  1087→		Module: module,
  1088→	}, nil
  1089→}
  1090→
  1091→// parseExternDef parses an extern function declaration
  1092→func (p *Parser) parseExternDef() (*ast.ExternDef, error) {
  1093→	if !p.match(lexer.TknExtern) {
  1094→		return nil, nil
  1095→	}
  1096→
  1097→	// Expect 'fn' keyword
  1098→	if !p.match(lexer.TknFn) {
  1099→		return nil, fmt.Errorf("expected 'fn' after 'extern' at %d:%d", p.current().Line, p.current().Column)
  1100→	}
  1101→
  1102→	name := p.current().Text
  1103→	if !p.match(lexer.TknIdentifier) {
  1104→		return nil, fmt.Errorf("expected function name at %d:%d", p.current().Line, p.current().Column)
  1105→	}
  1106→
  1107→	if !p.match(lexer.TknLParen) {
  1108→		return nil, fmt.Errorf("expected '(' at %d:%d", p.current().Line, p.current().Column)
  1109→	}
  1110→
  1111→	params := []ast.Parameter{}
  1112→	if !p.check(lexer.TknRParen) {
  1113→		for {
  1114→			paramName := p.current().Text
  1115→			if !p.match(lexer.TknIdentifier) {
  1116→				return nil, fmt.Errorf("expected parameter name at %d:%d", p.current().Line, p.current().Column)
  1117→			}
  1118→
  1119→			if !p.match(lexer.TknColon) {
  1120→				return nil, fmt.Errorf("expected ':' at %d:%d", p.current().Line, p.current().Column)
  1121→			}
  1122→
  1123→			typ := p.parseType()
  1124→
  1125→			params = append(params, ast.Parameter{
  1126→				Name: paramName,
  1127→				Type: typ,
  1128→			})
  1129→
  1130→			if !p.check(lexer.TknComma) {
  1131→				break
  1132→			}
  1133→			p.advance()
  1134→		}
  1135→	}
  1136→
  1137→	if !p.match(lexer.TknRParen) {
  1138→		return nil, fmt.Errorf("expected ')' at %d:%d", p.current().Line, p.current().Column)
  1139→	}
  1140→
  1141→	returnType := p.parseType()
  1142→
  1143→	return &ast.ExternDef{
  1144→		Name:       name,
  1145→		Parameters: params,
  1146→		ReturnType: returnType,
  1147→	}, nil
  1148→}
