  1150→// peekAhead returns the token at offset positions ahead
  1151→func (p *Parser) peekAhead(offset int) *lexer.Token {
  1152→	if p.pos+offset >= len(p.tokens) {
  1153→		return nil
  1154→	}
  1155→	return &p.tokens[p.pos+offset]
  1156→}
